using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type" in EF 9.
        // Restore old name for backward compatibility with existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id format changed from "EntityType|KeyValue" to just "KeyValue" in EF 9.
        // Restore old format for backward compatibility with existing documents.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdGenerator>();

        // Breaking change 3: HasIndex is no longer supported for Cosmos provider in EF 9.
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

    // For raw SQL queries that reference "Discriminator", no code change needed here,
    // but queries like: SELECT * FROM c WHERE c.Discriminator = 'Blog'
    // will continue to work because we preserved the "Discriminator" property name above.
}

// Custom ID value generator to preserve the legacy "Discriminator|Key" id format
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
    {
        var entityType = entry.Metadata.ShortName();
        var key = entry.Property("Id").CurrentValue?.ToString() ?? Guid.NewGuid().ToString();
        return $"{entityType}|{key}";
    }
}

